"use client";

import { useEffect, useRef, useState } from "react";
import { colorSwatches, resolveSwatchHex } from "@/lib/colorSwatches";
import type { EditorElement } from "@/lib/editorElements";
import { ToolIcon } from "./icons";
import { NativeColorInput } from "./NativeColorInput";

type FormTextElement = Extract<EditorElement, { type: "form-text" }>;

// Same shape as DropdownEditToolbar (border color, align, font size, font
// color, a settings popover, duplicate/delete) — form-text just doesn't have
// an options list, so its popover is only field name + required.
export function FormTextEditToolbar({
  element,
  topPt,
  heightPt,
  scale,
  onUpdate,
  onDuplicate,
  onDelete,
}: {
  element: FormTextElement;
  topPt: number;
  heightPt: number;
  scale: number;
  onUpdate: (patch: Partial<FormTextElement>) => void;
  onDuplicate?: () => void;
  onDelete: () => void;
}) {
  const [openMenu, setOpenMenu] = useState<"border" | "color" | "settings" | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!openMenu) return;
    const onOutsidePointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpenMenu(null);
    };
    document.addEventListener("pointerdown", onOutsidePointerDown);
    return () => document.removeEventListener("pointerdown", onOutsidePointerDown);
  }, [openMenu]);

  const topAbove = topPt * scale - 44;
  const top = topAbove >= 0 ? topAbove : topPt * scale + heightPt * scale + 6;

  const baseLeft = element.xPt * scale;
  const [left, setLeft] = useState(baseLeft);
  useEffect(() => setLeft(baseLeft), [baseLeft]);

  useEffect(() => {
    const node = rootRef.current;
    if (!node) return;
    const overflowRight = node.getBoundingClientRect().right - (window.innerWidth - 8);
    if (overflowRight > 0) setLeft((current) => Math.max(8, current - overflowRight));
  }, [left, openMenu]);

  return (
    <div
      ref={rootRef}
      onPointerDown={(event) => event.stopPropagation()}
      className="absolute z-20 flex items-center gap-0.5 rounded-lg border border-primary/30 bg-base-100 p-1 shadow-lg"
      style={{ left, top }}
    >
      <div className="relative">
        <button
          type="button"
          onClick={() => setOpenMenu((current) => (current === "border" ? null : "border"))}
          className="btn btn-ghost btn-xs btn-square relative"
          title={`Border color (currently ${element.borderColor})`}
        >
          <ToolIcon name="shape-rect" className="h-3.5 w-3.5" />
          <span
            className="absolute right-0 bottom-0 h-2 w-2 rounded-full border border-base-100"
            style={{ backgroundColor: element.borderColor }}
          />
        </button>
        {openMenu === "border" && (
          <div className="absolute top-full left-0 z-30 mt-1 flex gap-2 rounded-box bg-base-100 p-2 shadow-lg">
            {colorSwatches.map((swatch) => (
              <button
                key={swatch.id}
                type="button"
                onClick={() => {
                  onUpdate({ borderColor: resolveSwatchHex(swatch.id) });
                  setOpenMenu(null);
                }}
                aria-label={`Use ${swatch.id} border color`}
                title={`${swatch.id} (${resolveSwatchHex(swatch.id)})`}
                className={`h-7 w-7 rounded-full ${swatch.className}`}
              />
            ))}
            <label className="relative flex h-7 w-7 items-center justify-center rounded-full border border-base-300">
              <div
                className="absolute inset-0 rounded-full"
                style={{ background: "conic-gradient(red, yellow, lime, cyan, blue, magenta, red)" }}
              />
              <NativeColorInput
                value={element.borderColor}
                onChange={(color) => onUpdate({ borderColor: color })}
                className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
              />
            </label>
          </div>
        )}
      </div>

      <span className="mx-0.5 h-4 w-px bg-base-300" />

      <div className="flex items-center gap-0.5">
        <button
          type="button"
          onClick={() => onUpdate({ align: "left" })}
          className={`btn btn-xs btn-square ${element.align === "left" ? "btn-primary" : "btn-ghost"}`}
          title="Align left"
        >
          <ToolIcon name="align-left" className="h-3.5 w-3.5" />
        </button>
        <button
          type="button"
          onClick={() => onUpdate({ align: "center" })}
          className={`btn btn-xs btn-square ${element.align === "center" ? "btn-primary" : "btn-ghost"}`}
          title="Align center"
        >
          <ToolIcon name="align-center" className="h-3.5 w-3.5" />
        </button>
        <button
          type="button"
          onClick={() => onUpdate({ align: "right" })}
          className={`btn btn-xs btn-square ${element.align === "right" ? "btn-primary" : "btn-ghost"}`}
          title="Align right"
        >
          <ToolIcon name="align-right" className="h-3.5 w-3.5" />
        </button>
      </div>

      <span className="mx-0.5 h-4 w-px bg-base-300" />

      <div className="flex items-center gap-0.5">
        <button
          type="button"
          onClick={() => onUpdate({ fontSizePt: Math.max(6, Math.round(element.fontSizePt) - 1) })}
          className="btn btn-ghost btn-xs btn-square"
          aria-label="Decrease font size"
          title="Decrease font size"
        >
          <ToolIcon name="minus" className="h-3 w-3" />
        </button>
        <input
          type="number"
          min={6}
          max={72}
          value={Math.round(element.fontSizePt)}
          onChange={(event) => onUpdate({ fontSizePt: Number(event.target.value) || element.fontSizePt })}
          className="input input-bordered input-xs w-10 px-1 text-center [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
          aria-label="Font size"
          title="Font size"
        />
        <button
          type="button"
          onClick={() => onUpdate({ fontSizePt: Math.min(72, Math.round(element.fontSizePt) + 1) })}
          className="btn btn-ghost btn-xs btn-square"
          aria-label="Increase font size"
          title="Increase font size"
        >
          <ToolIcon name="plus" className="h-3 w-3" />
        </button>
      </div>

      <span className="mx-0.5 h-4 w-px bg-base-300" />

      <div className="relative">
        <button
          type="button"
          onClick={() => setOpenMenu((current) => (current === "color" ? null : "color"))}
          className="btn btn-ghost btn-xs btn-square relative"
          title={`Font color (currently ${element.textColor})`}
        >
          <ToolIcon name="palette" className="h-3.5 w-3.5" />
          <span
            className="absolute right-0 bottom-0 h-2 w-2 rounded-full border border-base-100"
            style={{ backgroundColor: element.textColor }}
          />
        </button>
        {openMenu === "color" && (
          <div className="absolute top-full left-0 z-30 mt-1 flex gap-2 rounded-box bg-base-100 p-2 shadow-lg">
            {colorSwatches.map((swatch) => (
              <button
                key={swatch.id}
                type="button"
                onClick={() => {
                  onUpdate({ textColor: resolveSwatchHex(swatch.id) });
                  setOpenMenu(null);
                }}
                aria-label={`Use ${swatch.id} color`}
                title={`${swatch.id} (${resolveSwatchHex(swatch.id)})`}
                className={`h-7 w-7 rounded-full ${swatch.className}`}
              />
            ))}
            <label className="relative flex h-7 w-7 items-center justify-center rounded-full border border-base-300">
              <div
                className="absolute inset-0 rounded-full"
                style={{ background: "conic-gradient(red, yellow, lime, cyan, blue, magenta, red)" }}
              />
              <NativeColorInput
                value={element.textColor}
                onChange={(color) => onUpdate({ textColor: color })}
                className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
              />
            </label>
          </div>
        )}
      </div>

      <span className="mx-0.5 h-4 w-px bg-base-300" />

      <div className="relative">
        <button
          type="button"
          onClick={() => setOpenMenu((current) => (current === "settings" ? null : "settings"))}
          className={`btn btn-xs gap-1 ${openMenu === "settings" ? "btn-primary" : "btn-ghost"}`}
          title="Field name & settings"
        >
          <ToolIcon name="form-field" className="h-3.5 w-3.5" />
          <ToolIcon name="chevron-down" className="h-3 w-3" />
        </button>

        {openMenu === "settings" && (
          <div className="absolute top-full left-0 z-30 mt-1 w-56 space-y-3 rounded-box border border-base-300 bg-base-100 p-3 shadow-lg">
            <label className="block text-xs font-medium text-base-content">
              Field name
              <input
                type="text"
                value={element.fieldName}
                onChange={(event) => onUpdate({ fieldName: event.target.value })}
                className="input input-bordered input-sm mt-1 w-full"
              />
            </label>

            <label className="flex items-center gap-2 text-sm text-base-content">
              <input
                type="checkbox"
                checked={element.required}
                onChange={(event) => onUpdate({ required: event.target.checked })}
                className="checkbox checkbox-sm"
              />
              Field is mandatory
            </label>
          </div>
        )}
      </div>

      {onDuplicate && (
        <>
          <span className="mx-0.5 h-4 w-px bg-base-300" />
          <button
            type="button"
            onClick={onDuplicate}
            className="btn btn-ghost btn-xs btn-square"
            aria-label="Duplicate"
            title="Duplicate"
          >
            <ToolIcon name="duplicate" className="h-3.5 w-3.5" />
          </button>
        </>
      )}

      <button
        type="button"
        onClick={onDelete}
        className="btn btn-ghost btn-xs btn-square text-error"
        aria-label={element.isExisting ? "Clear value" : "Delete"}
        // A field auto-detected from the uploaded PDF can't actually be
        // deleted (it's a real field in that file) — this clears its value
        // instead, so the label says what it actually does.
        title={element.isExisting ? "Clear value" : "Delete"}
      >
        <ToolIcon name={element.isExisting ? "eraser" : "trash"} className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { ToolIcon } from "./icons";
import { OfficeConvertWorkspace } from "./OfficeConvertWorkspace";
import { ConvertError, captureUrlToPdf } from "@/lib/convertClient";
import { describeError } from "@/lib/errorHelpers";

type Mode = "url" | "file";
type Status = "idle" | "working" | "done" | "error";

export function HtmlToPdfWorkspace() {
  const [mode, setMode] = useState<Mode>("url");
  const [url, setUrl] = useState("");
  const [status, setStatus] = useState<Status>("idle");
  const [statusMessage, setStatusMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");
  const [errorCode, setErrorCode] = useState<string | undefined>(undefined);
  const [result, setResult] = useState<{ downloadUrl: string; filename: string } | null>(null);

  function resetOutput() {
    setResult(null);
    setStatus("idle");
    setErrorMessage("");
    setErrorCode(undefined);
  }

  async function handleCapture() {
    if (!url.trim()) return;
    setStatus("working");
    setErrorMessage("");
    setErrorCode(undefined);

    try {
      const converted = await captureUrlToPdf(url.trim(), setStatusMessage);
      setResult(converted);
      setStatus("done");
    } catch (error) {
      setStatus("error");
      setErrorMessage(describeError(error, error instanceof Error ? error.message : "Couldn't convert this page."));
      setErrorCode(error instanceof ConvertError ? error.code : undefined);
    }
  }

  return (
    <div className="card border border-base-300 bg-base-100 p-6 shadow-sm">
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => {
            setMode("url");
            resetOutput();
          }}
          className={`flex-1 rounded-lg border px-3 py-2.5 text-left text-sm transition ${
            mode === "url"
              ? "border-primary bg-primary/5 text-base-content"
              : "border-base-300 text-base-content/70 hover:border-primary/40"
          }`}
        >
          <span className="block font-medium">From a URL</span>
          <span className="block text-xs text-base-content/50">Turn a live web page into a PDF</span>
        </button>
        <button
          type="button"
          onClick={() => {
            setMode("file");
            resetOutput();
          }}
          className={`flex-1 rounded-lg border px-3 py-2.5 text-left text-sm transition ${
            mode === "file"
              ? "border-primary bg-primary/5 text-base-content"
              : "border-base-300 text-base-content/70 hover:border-primary/40"
          }`}
        >
          <span className="block font-medium">From an HTML file</span>
          <span className="block text-xs text-base-content/50">Convert a saved .html file</span>
        </button>
      </div>

      {mode === "file" ? (
        <div className="mt-5">
          <OfficeConvertWorkspace
            inputFormat="html"
            outputFormat="pdf"
            accept=".html,.htm,text/html"
            icon="file"
            actionLabel="Convert to PDF"
          />
        </div>
      ) : (
        <div className="mt-5">
          <label className="block text-sm font-medium text-base-content">
            Web page URL
            <input
              type="url"
              value={url}
              onChange={(event) => {
                setUrl(event.target.value);
                resetOutput();
              }}
              placeholder="https://example.com"
              className="input input-bordered mt-1.5 w-full"
            />
          </label>

          <p className="mt-3 text-xs text-base-content/50">
            Uses{" "}
            <a href="https://cloudconvert.com" target="_blank" rel="noopener noreferrer" className="underline">
              CloudConvert
            </a>{" "}
            to render the page in a real browser on their servers — the page's own server just sees a normal
            visit, so anything behind a login or paywall won't come through.
          </p>

          {errorMessage && (
            <div className="mt-4 rounded-lg bg-error/10 px-3 py-2 text-sm text-error">
              <p>{errorMessage}</p>
              {errorCode === "AUTH_REQUIRED" && (
                <Link href="/login" className="mt-1 inline-block font-medium underline">
                  Log in
                </Link>
              )}
              {(errorCode === "QUOTA_EXCEEDED" || errorCode === "FILE_TOO_LARGE") && (
                <Link href="/pricing" className="mt-1 inline-block font-medium underline">
                  View plans
                </Link>
              )}
            </div>
          )}

          <div className="mt-5">
            {status === "done" && result ? (
              <a
                href={result.downloadUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-primary w-full"
              >
                <ToolIcon name="download" className="h-4 w-4" />
                Download {result.filename}
              </a>
            ) : (
              <button
                type="button"
                onClick={handleCapture}
                disabled={!url.trim() || status === "working"}
                className="btn btn-primary w-full"
              >
                {status === "working" ? statusMessage || "Converting..." : "Convert to PDF"}
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { EditorElement } from "@/lib/editorElements";
import { ToolIcon } from "./icons";

type ImageElement = Extract<EditorElement, { type: "image" }>;

export function ImageEditToolbar({
  element,
  scale,
  onUpdate,
  onDuplicate,
  onDelete,
}: {
  element: ImageElement;
  scale: number;
  onUpdate: (patch: Partial<ImageElement>) => void;
  onDuplicate: () => void;
  onDelete: () => void;
}) {
  const rootRef = useRef<HTMLDivElement>(null);

  const baseLeft = element.xPt * scale;
  const [left, setLeft] = useState(baseLeft);
  useEffect(() => setLeft(baseLeft), [baseLeft]);

  // On a narrow phone, an image near the page's right edge would otherwise
  // push this toolbar off-screen — nudge it back once its rendered width is
  // measurable.
  useEffect(() => {
    const node = rootRef.current;
    if (!node) return;
    const overflowRight = node.getBoundingClientRect().right - (window.innerWidth - 8);
    if (overflowRight > 0) setLeft((current) => Math.max(8, current - overflowRight));
  }, [left]);

  function rotateBy(deltaDeg: number) {
    onUpdate({ rotationDeg: (((element.rotationDeg + deltaDeg) % 360) + 360) % 360 });
  }

  return (
    <div
      ref={rootRef}
      onPointerDown={(event) => event.stopPropagation()}
      className="absolute z-20 flex items-center gap-0.5 rounded-lg border border-primary/30 bg-base-100 p-1 shadow-lg"
      style={{ left, top: Math.max(0, element.yPt * scale - 44) }}
    >
      <button
        type="button"
        onClick={() => rotateBy(-90)}
        className="btn btn-ghost btn-xs btn-square"
        aria-label="Rotate left"
        title="Rotate left 90°"
      >
