"use client";

import { useEffect, useRef, useState } from "react";
import { ToolIcon } from "./icons";
import { describeError } from "@/lib/errorHelpers";

type ImageItem = {
  id: string;
  file: File;
  previewUrl: string;
};

type Status = "idle" | "converting" | "done" | "error";

export function JpgToPdfWorkspace() {
  const inputRef = useRef<HTMLInputElement>(null);
  const [items, setItems] = useState<ImageItem[]>([]);
  const [status, setStatus] = useState<Status>("idle");
  const [errorMessage, setErrorMessage] = useState("");
  const [downloadUrl, setDownloadUrl] = useState<string | null>(null);
  const [progress, setProgress] = useState({ current: 0, total: 0 });

  const itemsRef = useRef(items);
  itemsRef.current = items;
  const downloadUrlRef = useRef(downloadUrl);
  downloadUrlRef.current = downloadUrl;

  useEffect(() => {
    return () => {
      itemsRef.current.forEach((item) => URL.revokeObjectURL(item.previewUrl));
      if (downloadUrlRef.current) URL.revokeObjectURL(downloadUrlRef.current);
    };
  }, []);

  function resetOutput() {
    if (downloadUrl) URL.revokeObjectURL(downloadUrl);
    setDownloadUrl(null);
    setStatus("idle");
    setErrorMessage("");
  }

  function addFiles(fileList: FileList | null) {
    if (!fileList || fileList.length === 0) return;
    const next = Array.from(fileList)
      .filter((file) => file.type === "image/jpeg" || file.type === "image/png")
      .map((file) => ({
        id: `${file.name}-${file.size}-${Math.random().toString(36).slice(2)}`,
        file,
        previewUrl: URL.createObjectURL(file),
      }));
    setItems((prev) => [...prev, ...next]);
    resetOutput();
  }

  function removeItem(id: string) {
    setItems((prev) => {
      const target = prev.find((item) => item.id === id);
      if (target) URL.revokeObjectURL(target.previewUrl);
      return prev.filter((item) => item.id !== id);
    });
    resetOutput();
  }

  function moveItem(index: number, direction: -1 | 1) {
    setItems((prev) => {
      const target = index + direction;
      if (target < 0 || target >= prev.length) return prev;
      const next = [...prev];
      [next[index], next[target]] = [next[target], next[index]];
      return next;
    });
  }

  async function handleConvert() {
    if (items.length === 0) return;
    setStatus("converting");
    setErrorMessage("");
    setProgress({ current: 0, total: items.length });

    try {
      const { PDFDocument } = await import("pdf-lib");
      const doc = await PDFDocument.create();

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const bytes = await item.file.arrayBuffer();
        const image = item.file.type === "image/png" ? await doc.embedPng(bytes) : await doc.embedJpg(bytes);
        const page = doc.addPage([image.width, image.height]);
        page.drawImage(image, { x: 0, y: 0, width: image.width, height: image.height });
        setProgress({ current: i + 1, total: items.length });
        // Yield to the browser so the progress bar actually paints between images
        // instead of jumping straight to 100% once the synchronous loop finishes.
        await new Promise((resolve) => setTimeout(resolve, 0));
      }

      const outBytes = await doc.save();
      const blob = new Blob([outBytes as BlobPart], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);
      setDownloadUrl(url);
      setStatus("done");
    } catch (error) {
      setStatus("error");
      setErrorMessage(describeError(error, error instanceof Error
          ? `Couldn't convert these images: ${error.message}`
          : "Couldn't convert these images.",));
    }
  }

  function convertAgain() {
    itemsRef.current.forEach((item) => URL.revokeObjectURL(item.previewUrl));
    if (downloadUrlRef.current) URL.revokeObjectURL(downloadUrlRef.current);
    setItems([]);
    setDownloadUrl(null);
    setStatus("idle");
    setErrorMessage("");
    setProgress({ current: 0, total: 0 });
  }

  if (status === "done" && downloadUrl) {
    return (
      <div className="card border border-base-300 bg-base-100 p-10 text-center shadow-sm">
        <span className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-success/10 text-success">
          <ToolIcon name="check" className="h-7 w-7" />
        </span>
        <h2 className="mt-4 text-lg font-semibold text-base-content">Your PDF is ready</h2>
        <p className="mt-1 text-sm text-base-content/60">
          {items.length} image{items.length === 1 ? "" : "s"} combined into one PDF.
        </p>
        <div className="mt-6 flex flex-col gap-2 sm:flex-row sm:justify-center">
          <a href={downloadUrl} download="images.pdf" className="btn btn-primary">
            <ToolIcon name="download" className="h-4 w-4" />
            Download PDF
          </a>
          <button type="button" onClick={convertAgain} className="btn btn-outline">
            Convert Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="card p-6">
      <div
        onDragOver={(event) => event.preventDefault()}
        onDrop={(event) => {
          event.preventDefault();
          addFiles(event.dataTransfer.files);
        }}
        className="flex min-h-48 flex-col items-center justify-center gap-3 rounded-xl px-6 py-8 text-center"
      >
        <span className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/10 text-primary">
          <ToolIcon name="upload" className="h-6 w-6" />
        </span>
        <p className="text-sm text-base-content/70">Drag & drop JPG or PNG files here, or</p>
        <button type="button" onClick={() => inputRef.current?.click()} className="btn btn-primary btn-md">
          Choose Images
        </button>
        <input
          ref={inputRef}
          type="file"
          multiple
          accept="image/jpeg,image/png"
          className="hidden"
          onChange={(event) => addFiles(event.target.files)}
        />
      </div>

      {items.length > 0 && (
        <ul className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
          {items.map((item, index) => (
            <li key={item.id} className="relative overflow-hidden rounded-lg border border-base-300">
              <span className="badge badge-neutral badge-sm absolute left-1.5 top-1.5 z-10">{index + 1}</span>
              <button
                type="button"
                onClick={() => removeItem(item.id)}
                disabled={status === "converting"}
                aria-label="Remove this image"
                title="Remove"
                className="btn btn-circle btn-error btn-xs absolute right-1.5 top-1.5 z-10"
              >
                <ToolIcon name="close" className="h-3 w-3" />
              </button>
              <div className="flex h-28 w-full items-center justify-center bg-base-200">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={item.previewUrl} alt={item.file.name} className="h-full w-full object-contain" />
              </div>
              <div className="flex items-center justify-center gap-1 bg-base-200 px-1.5 py-1">
                <button
                  type="button"
                  onClick={() => moveItem(index, -1)}
                  disabled={index === 0 || status === "converting"}
                  aria-label="Move earlier"
                  className="btn btn-ghost btn-xs btn-square"
                >
                  <ToolIcon name="chevron-down" className="h-3 w-3 rotate-90" />
                </button>
                <button
                  type="button"
                  onClick={() => moveItem(index, 1)}
                  disabled={index === items.length - 1 || status === "converting"}
                  aria-label="Move later"
                  className="btn btn-ghost btn-xs btn-square"
                >
                  <ToolIcon name="chevron-down" className="h-3 w-3 -rotate-90" />
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}

      {errorMessage && (
        <p className="mt-4 rounded-lg bg-error/10 px-3 py-2 text-sm text-error">{errorMessage}</p>
      )}

      {status === "converting" && (
        <div className="mt-5">
          <progress
            className="progress progress-primary w-full"
            value={progress.current}
            max={Math.max(progress.total, 1)}
          />
          <p className="mt-1 text-center text-xs text-base-content/60">
            Converting image {progress.current} of {progress.total}...
          </p>
        </div>
      )}

      <div className="mt-5">
        <button
          type="button"
          onClick={handleConvert}
          disabled={items.length === 0 || status === "converting"}
          className="btn btn-primary w-full"
        >
          {status === "converting" ? "Converting..." : "Convert to PDF"}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { colorSwatches, resolveSwatchHex } from "@/lib/colorSwatches";
import type { EditorElement } from "@/lib/editorElements";
import { ToolIcon } from "./icons";
import { NativeColorInput } from "./NativeColorInput";

// Line and arrow share the exact same shape (two endpoints, color, thickness) —
// arrow just adds a fixed arrowhead drawn from those same fields — so one
// toolbar serves both instead of a near-duplicate ArrowEditToolbar.
type LineElement = Extract<EditorElement, { type: "line" | "arrow" }>;

export function LineEditToolbar({
  element,
  scale,
  onUpdate,
  onDuplicate,
  onDelete,
}: {
  element: LineElement;
  scale: number;
  onUpdate: (patch: Partial<LineElement>) => void;
  onDuplicate: () => void;
  onDelete: () => void;
}) {
  const [openMenu, setOpenMenu] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!openMenu) return;
    const onOutsidePointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpenMenu(false);
    };
    document.addEventListener("pointerdown", onOutsidePointerDown);
    return () => document.removeEventListener("pointerdown", onOutsidePointerDown);
  }, [openMenu]);

  const leftPt = Math.min(element.x1Pt, element.x2Pt);
  const topPt = Math.min(element.y1Pt, element.y2Pt);

  const baseLeft = leftPt * scale;
  const [left, setLeft] = useState(baseLeft);
  useEffect(() => setLeft(baseLeft), [baseLeft]);

  // On a narrow phone, a line near the page's right edge would otherwise push
  // this toolbar off-screen — nudge it back once its rendered width is
  // measurable.
  useEffect(() => {
    const node = rootRef.current;
    if (!node) return;
    const overflowRight = node.getBoundingClientRect().right - (window.innerWidth - 8);
    if (overflowRight > 0) {
      setLeft((current) => Math.max(8, current - overflowRight));
    }
  }, [left]);

  return (
    <div
      ref={rootRef}
      onPointerDown={(event) => event.stopPropagation()}
      className="absolute z-20 flex items-center gap-0.5 rounded-lg border border-primary/30 bg-base-100 p-1 shadow-lg"
      style={{
        left,
        top: Math.max(0, topPt * scale - 44),
      }}
    >
      <div className="flex items-center gap-0.5" title="Line thickness">
        <button
          type="button"
          onClick={() => onUpdate({ strokeWidthPt: Math.max(1, Math.round(element.strokeWidthPt) - 1) })}
          className="btn btn-ghost btn-xs btn-square"
          aria-label="Decrease thickness"
          title="Decrease thickness"
        >
          <ToolIcon name="minus" className="h-3 w-3" />
        </button>
        <span className="w-4 text-center text-xs tabular-nums text-base-content/70">
          {Math.round(element.strokeWidthPt)}
        </span>
        <button
          type="button"
          onClick={() => onUpdate({ strokeWidthPt: Math.min(20, Math.round(element.strokeWidthPt) + 1) })}
          className="btn btn-ghost btn-xs btn-square"
          aria-label="Increase thickness"
          title="Increase thickness"
        >
          <ToolIcon name="plus" className="h-3 w-3" />
        </button>
      </div>

      <span className="mx-0.5 h-4 w-px bg-base-300" />

      <div className="relative">
        <button
          type="button"
          onClick={() => setOpenMenu((current) => !current)}
          className="btn btn-ghost btn-xs btn-square"
          title="Line color"
          style={{ color: element.color }}
        >
          <ToolIcon name="palette" className="h-3.5 w-3.5" />
        </button>
        {openMenu && (
          <div className="absolute top-full left-0 z-30 mt-1 flex gap-2 rounded-box bg-base-100 p-2 shadow-lg">
            {colorSwatches.map((swatch) => (
              <button
                key={swatch.id}
                type="button"
                onClick={() => {
                  onUpdate({ color: resolveSwatchHex(swatch.id) });
                  setOpenMenu(false);
                }}
                aria-label={`Use ${swatch.id} color`}
                title={`${swatch.id} (${resolveSwatchHex(swatch.id)})`}
                className={`h-7 w-7 rounded-full ${swatch.className}`}
              />
            ))}
            <label className="relative flex h-7 w-7 items-center justify-center rounded-full border border-base-300">
              <div
                className="absolute inset-0 rounded-full"
                style={{ background: "conic-gradient(red, yellow, lime, cyan, blue, magenta, red)" }}
              />
              <NativeColorInput
                value={element.color}
                onChange={(color) => onUpdate({ color })}
                className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
              />
            </label>
          </div>
        )}
      </div>

      <span className="mx-0.5 h-4 w-px bg-base-300" />

      <button
        type="button"
        onClick={onDuplicate}
        className="btn btn-ghost btn-xs btn-square"
        aria-label="Duplicate"
        title="Duplicate"
      >
        <ToolIcon name="duplicate" className="h-3.5 w-3.5" />
      </button>

      <button
        type="button"
        onClick={onDelete}
        className="btn btn-ghost btn-xs btn-square text-error"
        aria-label="Delete"
        title="Delete"
      >
        <ToolIcon name="trash" className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

